const original={};document.querySelectorAll('[data-t]').forEach(el=>original[el.dataset.t]=el.textContent);Object.assign(en,original);
const t=k=>(rows[lang]&&rows[lang][keys.indexOf(k)])||en[k]||k;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const size=n=>new Intl.NumberFormat(lang,{maximumFractionDigits:1}).format(n/1000)+' KB';
function invalidate(f){if(f.url)URL.revokeObjectURL(f.url);f.url=null;f.result=null;f.status='pending';}
function translate(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));renderGroups();render();}
$('#language').innerHTML=Object.entries(languages).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
try{lang=localStorage.getItem('formready-language')||navigator.language.split('-')[0]}catch{}if(!languages[lang])lang='en';$('#language').value=lang;
$('#language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('formready-language',lang)}catch{}translate()};
function options(values,current){return values.map(v=>`<option value="${v}" ${v===current?'selected':''}>${v==='jpeg'?'JPG':v.toUpperCase()}</option>`).join('')}
function renderGroups(){$('#groups').innerHTML=Object.entries(groups).map(([k,g],i)=>`<div class="group"><div class="grouphead"><span class="groupicon">${['▤','▧','✎'][i]}</span>${t(k)}</div><div class="groupfields"><label>${t('max')}<input data-group="${k}" data-field="max" type="number" min="1" max="25000" value="${g.max}"></label><label>${t('format')}<select data-group="${k}" data-field="format">${options(k==='document'?['pdf']:['jpeg','png','webp'],g.format)}</select></label></div></div>`).join('');$('#groups').querySelectorAll('input,select').forEach(el=>el.onchange=()=>{groups[el.dataset.group][el.dataset.field]=el.type==='number'?Number(el.value):el.value;for(const f of files)if(f.group===el.dataset.group){f[el.dataset.field]=groups[f.group][el.dataset.field];invalidate(f)}render()})}
function render(){const ready=files.filter(f=>f.result).length;$('#count').textContent=files.length;$('#total').textContent=files.length;$('#readyCount').textContent=ready;$('#prepare').disabled=!files.length||busy;$('#zip').disabled=!ready||busy;$('#clear').disabled=busy;$('#browse').disabled=busy;$('#demo').disabled=busy;$('#raster').disabled=busy;$('#groups').querySelectorAll('input,select').forEach(e=>e.disabled=busy);if(!files.length){$('#queue').innerHTML=`<div class="empty"><span>▤</span><h3>${t('empty')}</h3><p>${t('emptySub')}</p></div>`;return}
$('#queue').innerHTML=files.map(f=>`<article class="file" data-id="${f.id}"><div class="filetop">${f.thumb?`<img class="thumb" alt="" src="${f.thumb}">`:'<span class="thumb">PDF</span>'}<div class="fileinfo"><div class="filename">${esc(f.file.name)}</div><div class="filemeta">${size(f.file.size)} ${f.result?' → '+size(f.result.size):''}</div></div><button class="textbutton" data-action="remove" aria-label="${t('remove')} ${esc(f.file.name)}" ${busy?'disabled':''}>×</button></div><div class="filefields"><label>${t('format')} / ${t('limits')}<select data-field="group" ${busy?'disabled':''}>${['document','photo','signature'].map(k=>`<option value="${k}" ${f.group===k?'selected':''} ${f.pdf&&k!=='document'?'disabled':''}>${t(k)}</option>`).join('')}</select></label><label>${t('max')}<input data-field="max" type="number" min="1" value="${f.max}" ${busy?'disabled':''}></label>${!f.pdf?`<label>${t('width')}<input data-field="width" type="number" min="1" max="8000" placeholder="${t('auto')}" value="${f.width||''}" ${busy?'disabled':''}></label><label>${t('height')}<input data-field="height" type="number" min="1" max="8000" placeholder="${t('auto')}" value="${f.height||''}" ${busy?'disabled':''}></label>`:''}</div><div class="status ${f.error?'error':''}">${t(f.status)}${f.result?' · '+f.format.toUpperCase():''}</div>${f.result?`<div class="fileactions"><button class="textbutton" data-action="preview">${t('preview')}</button><a href="${f.url}" download="${esc(f.outputName)}">↓ ${t('save')}</a></div>`:''}</article>`).join('');
$('#queue').querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>{const f=files.find(f=>f.id===el.closest('article').dataset.id);const field=el.dataset.field;f[field]=field==='group'?el.value:Number(el.value);if(field==='group')Object.assign(f,groups[f.group]);invalidate(f);render()});$('#queue').querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const f=files.find(f=>f.id===el.closest('article').dataset.id);if(el.dataset.action==='remove'){invalidate(f);if(f.thumb)URL.revokeObjectURL(f.thumb);files=files.filter(x=>x!==f);render()}else{const body=$('#previewBody');body.replaceChildren();const view=document.createElement(f.format==='pdf'?'iframe':'img');view.src=f.url;view.title=f.outputName;view.alt=f.outputName;body.append(view);$('#preview').showModal()}})}
function add(incoming){if(busy)return;$('#notice').textContent='';for(const file of incoming){if(!/\.(pdf|jpe?g|png|webp)$/i.test(file.name)||file.size>25e6||files.length>=100||files.reduce((n,f)=>n+f.file.size,0)+file.size>150e6){$('#notice').textContent=t('unsupported');continue}const pdf=/\.pdf$/i.test(file.name),group=pdf?'document':/sign/i.test(file.name)?'signature':'photo';files.push({id:crypto.randomUUID(),file,pdf,group,...groups[group],width:0,height:0,status:'pending',thumb:pdf?null:URL.createObjectURL(file)})}render()}
$('#browse').onclick=()=>$('#files').click();$('#files').onchange=e=>{add(e.target.files);e.target.value=''};$('#drop').ondragover=e=>{e.preventDefault();$('#drop').classList.add('drag')};$('#drop').ondragleave=()=>$('#drop').classList.remove('drag');$('#drop').ondrop=e=>{e.preventDefault();$('#drop').classList.remove('drag');add(e.dataTransfer.files)};$('#clear').onclick=()=>{for(const f of files){invalidate(f);if(f.thumb)URL.revokeObjectURL(f.thumb)}files=[];render();$('#notice').textContent=''};$('#closePreview').onclick=()=>{$('#preview').close();$('#previewBody').replaceChildren()};$('#raster').onchange=()=>{files.filter(f=>f.pdf).forEach(invalidate);render()};
const blob=(c,type,q)=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('imageError')),type,q));
function canvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c}
async function imageResult(f){let img;try{img=await createImageBitmap(f.file)}catch{throw new Error('imageError')}try{if(img.width*img.height>60e6)throw new Error('imageError');let w=f.width||Math.round(img.width*(f.height?f.height/img.height:1)),h=f.height||Math.round(img.height*(f.width?f.width/img.width:1));let fmt=f.format==='pdf'?'jpeg':f.format,limit=Math.floor(f.max*1000)-1;
for(let attempt=0;attempt<12;attempt++){const c=canvas(w,h),ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,w,h);const ratio=Math.min(w/img.width,h/img.height);ctx.drawImage(img,(w-img.width*ratio)/2,(h-img.height*ratio)/2,img.width*ratio,img.height*ratio);let best=null,low=.25,high=.95;for(let i=0;i<(fmt==='png'?1:8);i++){const q=i===0?.95:(low+high)/2,b=await blob(c,'image/'+fmt,q);if(b.type!=='image/'+fmt)throw new Error('imageError');let output=b;if(f.format==='pdf'){const doc=await PDFLib.PDFDocument.create(),im=await doc.embedJpg(await b.arrayBuffer()),p=doc.addPage([w*.75,h*.75]);p.drawImage(im,{x:0,y:0,width:p.getWidth(),height:p.getHeight()});output=new Blob([await doc.save()],{type:'application/pdf'})}if(output.size<=limit){best=output;low=q}else high=q;if(fmt==='png'||(i===0&&best))break}c.width=c.height=1;if(best)return best;if(f.width||f.height)break;w=Math.max(1,Math.floor(w*.8));h=Math.max(1,Math.floor(h*.8));if(Math.min(w,h)<160)break}throw new Error('failed')}finally{img.close()}}
async function pdfResult(f){const bytes=new Uint8Array(await f.file.arrayBuffer()),limit=Math.floor(f.max*1000)-1;let doc;try{doc=await PDFLib.PDFDocument.load(bytes)}catch{throw new Error('pdfError')}const raw=new TextDecoder('latin1').decode(bytes);const signed=/\/ByteRange\s*\[/.test(raw)||doc.context.enumerateIndirectObjects().some(([,o])=>/\/FT\s*\/Sig\b/.test(o.toString()));if(bytes.length<=limit)return f.file;if(signed)throw new Error('signed');let optimized=await doc.save({useObjectStreams:true});if(optimized.length<=limit)return new Blob([optimized],{type:'application/pdf'});if(!$('#raster').checked)throw new Error('pdfBig');let pdf;try{pdf=await pdfjs.getDocument({data:bytes.slice(),isEvalSupported:false}).promise;if(pdf.numPages>40)throw new Error('tooManyPages');for(const [scale,q] of [[1.6,.8],[1.2,.65],[.9,.5],[.7,.35]]){const out=await PDFLib.PDFDocument.create();for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),vp=page.getViewport({scale:1}),s=Math.min(scale,2200/Math.max(vp.width,vp.height)),v=page.getViewport({scale:s}),c=canvas(Math.ceil(v.width),Math.ceil(v.height));await page.render({canvasContext:c.getContext('2d'),viewport:v,background:'white'}).promise;const jpg=await blob(c,'image/jpeg',q),im=await out.embedJpg(await jpg.arrayBuffer()),p=out.addPage([vp.width,vp.height]);p.drawImage(im,{x:0,y:0,width:vp.width,height:vp.height});c.width=c.height=1;page.cleanup()}const result=await out.save();if(result.length<=limit){f.rasterized=true;return new Blob([result],{type:'application/pdf'})}}throw new Error('failed')}finally{await pdf?.destroy()}}
$('#prepare').onclick=async()=>{busy=true;$('#notice').textContent='';$('#progress').hidden=false;$('#progress').max=files.length;$('#progress').value=0;for(const f of files){invalidate(f);f.error=false;f.rasterized=false;f.status='processing';render();await new Promise(r=>setTimeout(r,10));try{if(!Number.isFinite(f.max)||f.max<=0||f.max>25000||[f.width,f.height].some(n=>!Number.isFinite(n)||n<0||n>8000||!Number.isInteger(n)))throw new Error('invalid');f.result=await(f.pdf?pdfResult(f):imageResult(f));f.outputName=f.file.name.replace(/\.[^.]+$/,'').replace(/[\\/\x00-\x1f]/g,'_')+'-ready.'+(f.format==='jpeg'?'jpg':f.format);f.url=URL.createObjectURL(f.result);f.status=f.rasterized?'reviewStatus':'done'}catch(e){f.status=en[e.message]?e.message:'pdfError';f.error=true}$('#progress').value++;render()}busy=false;render();$('#notice').textContent=t('finished')};
$('#zip').onclick=async()=>{if(busy)return;busy=true;render();try{const entries={},report=[];for(const f of files.filter(f=>f.result)){let name=f.outputName,i=2;while(entries[name])name=f.outputName.replace(/(\.[^.]+)$/,`-${i++}$1`);entries[name]=new Uint8Array(await f.result.arrayBuffer());report.push({file:name,bytes:f.result.size,limitBytes:Math.floor(f.max*1000),imageBasedPDF:!!f.rasterized})}entries['formready-report.json']=strToU8(JSON.stringify(report,null,2));const url=URL.createObjectURL(new Blob([zipSync(entries,{level:0})],{type:'application/zip'}));const a=document.createElement('a');a.href=url;a.download='formready-files.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}finally{busy=false;render()}};
$('#demo').onclick=async()=>{if(busy)return;const batch=[];for(let i=1;i<=20;i++){const doc=await PDFLib.PDFDocument.create(),page=doc.addPage([595,842]);page.drawText('SAMPLE DOCUMENT '+i,{x:50,y:760,size:24});page.drawText('Synthetic test file. No personal information.',{x:50,y:710,size:12});batch.push(new File([await doc.save()],`Sample-document-${String(i).padStart(2,'0')}.pdf`,{type:'application/pdf'}))}for(const sign of [false,true]){const c=canvas(sign?900:1200,sign?300:1600),ctx=c.getContext('2d');ctx.fillStyle=sign?'#fff':'#c7dbd2';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#234b40';ctx.font=sign?'italic 90px serif':'bold 85px sans-serif';ctx.fillText(sign?'Sample Signature':'SAMPLE PHOTO',40,sign?170:800);batch.push(new File([await blob(c,'image/png')],sign?'Sample-signature.png':'Sample-photo.png',{type:'image/png'}))}add(batch)};translate();
